WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_multiple_compare'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '倍数比较', 'kp-xingce-data-multiple-compare', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "倍数比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "比较四个选项中 A/B 的大小。摒弃除法，全用乘法验证是其终极密码。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“以下哪个月份/省份，A的产量是B产量的倍数最高/最低？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式与法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "本质是分数比较法则："}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 大大则大：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 找分子最大、分母最小的那个绝世神仙，直接秒杀为最大倍数。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 化除为乘：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 不做 A÷B，而是用试金石 k 乘以 B 去验证是否达到 A。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出四个选项的分子A和分母B] --> B[先找极端项排雷]\nB --> C[选定一个选项A1/B1估算大概倍数 k]\nC --> D[用 k 乘以其他选项的分母B]\nD --> E{B × k 与 A 的关系}\nE -- B×k < A --> F[说明该选项的真实倍数大于 k, 将 A1 淘汰]\nE -- B×k > A --> G[说明该选项的真实倍数小于 k]\nG --> H[通过不断试错收敛出最大/最小值]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A/B数据如下：甲(400/100)、乙(500/120)、丙(650/150)。求倍数最高的是？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看甲的倍数：400 / 100 = 4倍。把 4 作为试金石 k。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "验乙：120 × 4 = 480。乙的真实分子是 500 > 480，说明乙的倍数 > 4。甲被淘汰！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "验丙：150 × 4 = 600。丙真实分子 650 > 600，丙也大于4。且丙(650/150)和乙(500/120)需进一步对比。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "乙丙比拼：乙约 4.1倍，丙约 4.3倍。所以丙最大。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "死算四个竖式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多考生遇到这种题，真的会在草稿纸上列四个除法竖式，算出每个选项带两位小数的结果。这种低效操作是考场大忌。人类大脑对乘法的敏感度和速度远高于除法！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "在平时训练中，强制没收自己做除法的权力，遇到任何比大小题全用“乘法逼近”的思路去破局。"}]}]}$$ AS jsonb), NULL, '倍数比较的核心考点与实战推导。', category_node.id, CAST('["资料分析", "倍数比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_multiple_compare", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
